// TC-PERF-001: load profile for POST /v1/duplicate-checks.
// Synthetic payloads only (generated by scripts/generate_test_data.py --seed 42).
// The suite seeds its own claims in setup(): the duplicate-check endpoint requires an
// existing claim in the caller's tenant, so payload claim_ids are replaced with seeded ones.
import http from 'k6/http';
import { check } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { SharedArray } from 'k6/data';

const BASE = __ENV.BASE_URL || 'http://localhost:3100/api/v1';
const TENANT = __ENV.TENANT_ID || 'ten_k6_load';
const ROLE = __ENV.DEMO_ROLE || 'claims_manager';
const failureRate = new Rate('duplicate_check_failure_rate');
const latency = new Trend('duplicate_check_latency_ms', true);

const payloads = new SharedArray('duplicate-check payloads', () =>
  JSON.parse(open('./data/duplicate-check-payloads.json')),
);

const HEADERS = {
  'Content-Type': 'application/json',
  'Origin': 'http://localhost:3100',
  'x-nahashield-demo-role': ROLE,
  'x-tenant-id': TENANT,
};

export const options = {
  scenarios: {
    load: { executor: 'ramping-vus', startVUs: 0, stages: [
      { duration: '1m', target: 10 }, { duration: '3m', target: 10 },
      { duration: '1m', target: 25 }, { duration: '3m', target: 25 },
      { duration: '1m', target: 0 },
    ] },
  },
  thresholds: {
    duplicate_check_latency_ms: ['p(95)<1500'],
    duplicate_check_failure_rate: ['rate<0.05'],
    checks: ['rate>0.99'],
  },
};

// Seed claims in the load tenant; duplicate-checks run against these ids.
export function setup() {
  const ids = [];
  let cookie = '';
  for (let i = 0; i < 25; i += 1) {
    const res = http.post(`${BASE}/claims`, JSON.stringify({
      policy_id: `pol_k6_${i}`,
      claim_type: 'life',
      amount_claimed_cents: 100000 + i * 1000,
      consent_id: `cns_k6_${i}`,
      channel: 'load_test',
      deceased_person_id: `hash_k6_dec_${i % 5}`,
      claimant_person_id: `hash_k6_clm_${i % 7}`,
      agent_id: `agt_k6_${i % 3}`,
      documents: [{ document_type: 'death_notice', sha256_hash: `doc_k6_${i % 4}` }],
    }), { headers: { ...HEADERS, 'Idempotency-Key': `k6-seed-${i}` } });
    if (res.status !== 201) throw new Error(`seed claim ${i} failed: ${res.status} ${res.body}`);
    ids.push(res.json().claim_id);
    if (i === 0) {
      const ws = res.cookies.nahashield_workspace;
      cookie = ws && ws[0] ? `nahashield_workspace=${ws[0].value}` : '';
    }
  }
  // Reuse one workspace cookie for the whole run: without it the isolation middleware
  // creates a new synthetic workspace per request and the run hits its 200-workspace cap (503).
  if (!cookie) throw new Error('no workspace cookie issued by seed response');
  return { claimIds: ids, cookie };
}

export default function (data) {
  const payload = payloads[Math.floor(Math.random() * payloads.length)];
  const claimId = data.claimIds[Math.floor(Math.random() * data.claimIds.length)];
  const body = JSON.stringify({
    ...payload,
    tenant_id: TENANT,
    claim_id: claimId,
    request_id: `req_k6_${__VU}_${__ITER}`,
    consent_id: 'cns_k6_load',
    // Rotate the scope so repeat checks on one claim are not all idempotent replays.
    check_scope: payload.check_scope.slice(0, (__ITER % payload.check_scope.length) + 1),
  });
  const headers = {
    ...HEADERS,
    'Cookie': data.cookie,
    'Idempotency-Key': `k6-dup-${__VU}-${__ITER}`,
    'x-request-id': `req_k6_${__VU}_${__ITER}`,
  };
  const res = http.post(`${BASE}/duplicate-checks`, body, { headers });
  latency.add(res.timings.duration);
  const ok = check(res, {
    'status is 200/201/202': (r) => r.status === 200 || r.status === 201 || r.status === 202,
    'response has duplicate_check_id': (r) => {
      try { return !!r.json().duplicate_check_id; } catch (e) { return false; }
    },
    // A 202 idempotent replay (TC-DUP-031) returns no score; a fresh 201 must carry one.
    'fresh check has duplicate_risk_score': (r) => {
      try { const j = r.json(); return j.idempotent === true || typeof j.duplicate_risk_score === 'number'; } catch (e) { return false; }
    },
  });
  failureRate.add(!ok);
}
